package com.lovemaptually.controller;import com.lovemaptually.auth.CurrentUser;import com.lovemaptually.common.ApiResponse;import com.lovemaptually.dto.response.GroupPreferencesResponse;import com.lovemaptually.service.PreferenceService;import lombok.RequiredArgsConstructor;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/groups/{groupId}/preferences") @RequiredArgsConstructor public class PreferenceController {private final PreferenceService service;@GetMapping ApiResponse<GroupPreferencesResponse> get(Authentication a,@PathVariable long groupId){return ApiResponse.of(200,"조회했습니다",service.get(CurrentUser.id(a),groupId));}}
